const app = document.querySelector('#app');
const titles = {inicio:'Visão geral',decisao:'Nova decisão',rotina:'Minha rotina',experimento:'Experimento',resultados:'Resultados'};
const sample = {name:'Aprender a tocar violão',category:'Hobby',why:'Quero ter um momento criativo para mim e aprender minhas músicas favoritas.',minutes:30,frequency:3,cost:0,free:[1,1,1,1,1,2,2],sessions:[{done:false,actual:0},{done:false,actual:0},{done:false,actual:0}],reflection:'Gostei mais quando pratiquei depois do jantar.',choice:'',demo:true};
// O protótipo guarda uma decisão neste navegador. Um backend pode substituir esta camada depois.
let state = Learning.migrate(sample);
let storageWarning = false;
try {
  const raw = localStorage.getItem('antes-v2') || localStorage.getItem('antes-v1');
  if (raw) {
    const saved = JSON.parse(raw);
    if (Learning.validate(saved)) state = Learning.migrate(saved);
    else storageWarning = true;
  }
} catch { storageWarning = true; }
function save() {
  try { localStorage.setItem('antes-v2', JSON.stringify(state)); return true; }
  catch { toast('Não foi possível salvar. Mantenha a aba aberta e libere espaço no navegador.'); return false; }
}
let toastTimer;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
const esc = value => String(value).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const total = () => state.sessions.filter(s=>s.done).length;
const heading = (title,sub,action='') => `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;
function home(){return heading('Suas próximas possibilidades.','Uma escolha de cada vez. No seu tempo.','<a class="btn primary" href="#decisao">＋ Nova decisão</a>')+`<section class="welcome"><div class="welcome-copy"><div class="eyebrow" style="color:var(--blue)">MENOS SUPOSIÇÕES. MAIS EXPERIÊNCIAS.</div><h2>Antes de dar o próximo passo,<br>experimente.</h2><p>Descubra como uma nova ideia cabe na sua rotina, com pequenos testes no mundo real.</p><a class="text-link" href="#rotina">Explorar minha rotina ↗</a></div><div class="path"><div class="path-step"><b>▦</b>Simule</div><div class="path-separator"></div><div class="path-step"><b>◷</b>Experimente</div><div class="path-separator"></div><div class="path-step"><b>✓</b>Decida</div></div></section><div class="stats"><div class="stat"><div class="stat-label">Decisão em foco</div><div class="stat-number">01</div><small>${esc(state.category)} em exploração</small></div><div class="stat"><div class="stat-label">Sessões realizadas</div><div class="stat-number">${total()}<span class="muted" style="font-size:18px"> / ${state.frequency}</span></div><small>Pequenos passos contam</small></div><div class="stat"><div class="stat-label">Tempo experimentado</div><div class="stat-number">${state.sessions.reduce((n,s)=>n+s.actual,0)} <span class="muted" style="font-size:16px">min</span></div><small>Aprendizado na prática</small></div></div><div class="section-heading"><h2>O que você está explorando</h2>${state.demo?'<span class="tag">EXEMPLO INTERATIVO</span>':''}</div><div class="decision-grid"><article class="card"><div class="card-top"><span class="activity-icon">${Learning.detect(state.name)?.id==='guitar'?'♫':'✦'}</span><span class="tag green">${state.choice?'Decisão registrada':'Em experimento'}</span></div><h2>${esc(state.name)}</h2><p>${esc(state.why)}</p><div class="row" style="font-size:12px"><span class="muted">Sua jornada de aprendizado</span><strong>${total()} de ${state.frequency} sessões</strong></div><div class="progress"><span style="width:${total()/state.frequency*100}%"></span></div><div class="card-bottom row"><span class="muted">${state.minutes} min por sessão</span><a class="text-link" href="#experimento">Continuar experimento →</a></div></article><aside class="card insight"><div class="eyebrow">UMA IDEIA PARA LEVAR</div><h3>Você não precisa decidir tudo hoje.</h3><p>Um pequeno teste pode revelar mais do que semanas imaginando como seria.</p><hr style="border:0;border-top:1px solid #ffffff24;margin:25px 0"><small>Observe o que funciona. Ajuste o que precisar.</small></aside></div>`;}
const steps = active => `<div class="steps">${['Sua ideia','Sua rotina','Seu experimento'].map((s,i)=>`<div class="${i===active?'current':''}"><span>${i+1}</span> ${s}</div>${i<2?' → ':''}`).join('')}</div>`;
function decision(){return heading('Toda escolha começa com uma ideia.','O que você está pensando em trazer para sua vida?')+steps(0)+`<div class="form-layout"><form id="decision-form" class="card"><div class="field"><label for="name">Quero começar…</label><input id="name" name="name" placeholder="Ex.: fazer um curso de inglês" required maxlength="100"></div><div class="field"><label for="category">Tipo de atividade</label><select name="category" id="category"><option>Curso</option><option>Hobby</option><option>Atividade física</option><option>Outro</option></select></div><div class="field"><label for="why">Por que isso é importante para você?</label><textarea id="why" name="why" maxlength="500" placeholder="O que você espera aprender, sentir ou mudar?" required></textarea></div><div class="two-col"><div class="field"><label for="minutes">Minutos por sessão</label><input type="number" name="minutes" id="minutes" min="5" max="240" step="5" value="30" required></div><div class="field"><label for="frequency">Sessões por semana</label><input type="number" name="frequency" id="frequency" min="1" max="7" value="3" required></div></div><div class="field"><label for="cost">Custo estimado do teste (R$)</label><input type="number" name="cost" id="cost" min="0" max="999999" step="0.01" value="0" required><small>Considere um teste acessível antes de um investimento maior.</small></div><div class="hint">Este protótipo acompanha uma decisão por vez. Ao continuar, você substitui ${state.demo?'o exemplo':'sua decisão atual e os registros dela'}.</div><div class="form-actions"><a class="btn" href="#inicio">Voltar</a><button class="btn primary">Simular minha rotina →</button></div></form><aside class="card"><div class="eyebrow" style="color:var(--blue)">COMECE PEQUENO</div><h2 style="margin-top:15px">Uma experiência,<br>não uma obrigação.</h2><p>Escolha algo que você consiga experimentar na próxima semana.</p><div class="message">“Quero aprender inglês” pode começar com três sessões de 30 minutos usando uma aula introdutória.</div><p>Inclua preparação e deslocamento no tempo de cada sessão, quando necessário.</p></aside></div>`;}
function summary(free){const required=state.minutes*state.frequency;const available=free.reduce((a,b)=>a+b,0)*60;const slots=free.reduce((a,h)=>a+Math.floor(h*60/state.minutes),0);const fits=slots>=state.frequency;return `<div class="eyebrow" style="color:var(--blue)">SUA SIMULAÇÃO</div><div class="result-number">${(required/60).toLocaleString('pt-BR',{maximumFractionDigits:1})}<span style="font-size:20px"> h / semana</span></div><p>${state.frequency} sessões de ${state.minutes} minutos</p><hr style="border:0;border-top:1px solid var(--line);margin:23px 0"><h3>${fits?'Há espaço para testar.':'Talvez seja preciso ajustar.'}</h3><p>Você informou ${(available/60).toLocaleString('pt-BR')} horas livres e espaço estimado para ${slots} sessões.</p><div class="hint">${fits?'O total informado comporta o plano. Verifique se o tempo de cada dia está disponível em um bloco contínuo.':'O plano não cabe nos blocos informados. Ajuste sua disponibilidade ou crie uma decisão com sessões menores.'}</div><p style="font-size:12px">Estimativa baseada nos dados que você informou. Horários exatos e conflitos de agenda ainda não são verificados.</p>`;}
function routine(){return heading('Cabe na sua semana?','Simule o espaço disponível para '+esc(state.name.toLowerCase())+'.')+steps(1)+`<div class="form-layout"><form id="routine-form" class="card"><h2>Tempo livre por dia</h2><p>Desconte sono, trabalho, aulas e compromissos. Considere uma margem para descanso e imprevistos.</p><div class="week">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map((d,i)=>`<div class="day"><label for="day${i}">${d}</label><input id="day${i}" name="day${i}" type="number" min="0" max="16" step="0.5" required value="${state.free[i]}" aria-label="Horas livres em ${d}"><small>horas</small></div>`).join('')}</div><div class="hint">Use horas: 0,5 equivale a 30 minutos. Distribua apenas o tempo que você realmente quer disponibilizar.</div><div class="form-actions"><a class="btn" href="#decisao">Rever minha ideia</a><button class="btn primary">Salvar e ver experimento →</button></div></form><aside class="card" id="simulation" aria-live="polite">${summary(state.free)}</aside></div>`;}
function results(){const done=total(),actual=state.sessions.reduce((n,s)=>n+s.actual,0),planned=state.frequency*state.minutes;return heading('O que a experiência te mostrou?','Use seus registros para escolher o próximo passo.',state.demo?'<span class="tag">DADOS DE EXEMPLO</span>':'')+studyResults()+`<section class="card"><div class="row"><div><div class="eyebrow muted">SUA DECISÃO</div><h2 style="margin-top:8px">${esc(state.name)}</h2></div><span class="tag ${done===state.frequency?'green':'blue'}">${done===state.frequency?'Jornada concluída':'Resultado parcial'}</span></div><div class="comparison"><div><div class="result-number">${done}<span style="font-size:20px;color:var(--muted)"> de ${state.frequency}</span></div><p>Sessões realizadas · ${Math.round(done/state.frequency*100)}% do plano</p></div><div><div class="chart-row"><div class="row"><span>Tempo previsto na semana</span><strong>${planned} min</strong></div><div class="progress"><span style="width:${planned/Math.max(planned,actual)*100}%;background:#b4c3f4"></span></div></div><div class="chart-row"><div class="row"><span>Tempo realizado até agora</span><strong>${actual} min</strong></div><div class="progress"><span style="width:${actual/Math.max(planned,actual)*100}%"></span></div></div></div></div><h3>Sua percepção</h3><p style="white-space:pre-wrap">${esc(state.reflection||'Você ainda não registrou uma reflexão. Volte ao experimento para contar como foi.')}</p>${done===0?'<div class="hint">Registre pelo menos uma sessão para começar a comparar sua experiência.</div>':done<state.frequency?'<div class="hint">Ainda há sessões sem registro. O tempo inclui a prática em andamento. Sessões contam após concluir todas as etapas.</div>':'<div class="hint">Você completou o plano. Considere também satisfação, custo e disposição para continuar.</div>'}</section><form id="choice-form" class="card" style="margin-top:22px"><h2>Qual será seu próximo passo?</h2><p>Você pode mudar de ideia. O importante é usar o que aprendeu.</p><label for="choice">Minha escolha</label><select id="choice" required><option value="">Selecione uma opção</option>${['Continuar com a atividade','Adaptar o plano','Experimentar mais um pouco','Deixar para outro momento'].map(c=>`<option ${state.choice===c?'selected':''}>${c}</option>`).join('')}</select><div class="form-actions"><a class="btn" href="#experimento">Voltar aos registros</a><button class="btn primary">Salvar minha escolha ✓</button></div></form>`;}
function bind(){document.querySelector('#decision-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),why=f.get('why').trim();if(!name||!why){toast('Preencha sua ideia e seu motivo.');return;}resetStudy();state={name,why,category:f.get('category'),minutes:Number(f.get('minutes')),frequency:Number(f.get('frequency')),cost:Number(f.get('cost')),free:[...state.free],sessions:Array.from({length:Number(f.get('frequency'))},Learning.newSession),reflection:'',choice:'',demo:false,schema:2,customCards:[],cardProgress:{},attempts:[],legacyHistory:[]};save();location.hash='rotina';});
const rf=document.querySelector('#routine-form');rf?.addEventListener('input',()=>{if(rf.checkValidity())document.querySelector('#simulation').innerHTML=summary(Array.from({length:7},(_,i)=>Number(rf.elements['day'+i].value)));});rf?.addEventListener('submit',e=>{e.preventDefault();state.free=Array.from({length:7},(_,i)=>Number(rf.elements['day'+i].value));save();location.hash='experimento';});
bindStudy();
document.querySelector('#choice-form')?.addEventListener('submit',e=>{e.preventDefault();state.choice=document.querySelector('#choice').value;if(save())toast('Sua escolha foi salva neste navegador.');});}
function render(){const route=location.hash.slice(1)||'inicio';const valid=titles[route]?route:'inicio';document.querySelector('#breadcrumb').textContent='Meu espaço / '+titles[valid];document.querySelectorAll('[data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===valid);if(a.dataset.route===valid)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});app.innerHTML=({inicio:home,decisao:decision,rotina:routine,experimento:experiment,resultados:results})[valid]();document.title=titles[valid]+' · Antes';bind();}
window.addEventListener('hashchange',()=>{render();app.focus({preventScroll:true});window.scrollTo(0,0);});render();
// Integração opcional: a navegação funciona normalmente em navegadores sem WebMCP.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'navigate_antes',description:'Abre uma das cinco telas do Antes sem alterar os registros.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:Object.keys(titles)}},required:['screen'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Object.hasOwn(titles,input.screen))throw new Error('Tela inválida');history.replaceState(null,'','#'+input.screen);render();return {screen:input.screen};}})).catch(()=>{});}catch{/* Navegação manual continua disponível. */}}

setupTheme();
if (storageWarning) toast('Não foi possível recuperar os dados salvos. O exemplo foi aberto; os dados anteriores não foram apagados.');
window.addEventListener('storage', event => {
  if (event.key !== 'antes-v2' || !event.newValue) return;
  try {
    const incoming = JSON.parse(event.newValue);
    if (!Learning.validate(incoming)) return;
    stopTimer(false);
    state = Learning.migrate(incoming);
    quizQuestions = []; quizFeedback = null; quizAnswers = {};
    render();
  } catch { /* Não importa conteúdo inválido de outra aba. */ }
});
